#nullable enable // autogenerated

using MukioI18n;
using MVZ2.GameContent.Contraptions;
using MVZ2.Vanilla.Definitions;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Localization;
using MVZ2.Vanilla.RandomChina;
using MVZ2Logic.Grids;
using PVZEngine.Entities;
using PVZEngine.Tools.Random;

namespace MVZ2.GameContent.RandomChinaEvents
{
    [RandomChinaEventDefinition(VanillaRandomChinaEventNames.theHighPriestess)]
    public class TheHighPriestessEvent : RandomChinaEventDefinition
    {
        public TheHighPriestessEvent(string nsp, string path) : base(nsp, path, NAME, DESCRIPTION, 99999999f)
        {
        }
        public override void Run(Entity contraption, RandomGenerator rng)
        {
            var level = contraption.Level;
            var column = contraption.GetColumn();
            var lane = contraption.GetLane();
            foreach (var direction in LogicGridExt.allTileDirections)
            {
                LogicGridExt.GetDirectionedTile(direction, column, lane, out var c, out var l);
                var grid = level.GetGrid(c, l);
                if (grid != null)
                {
                    var pos = grid.GetEntityPosition();
                    contraption.SpawnWithParams(VanillaContraptionID.onbashira, pos);
                }
            }
        }
        [TranslateMsg("随机瓷器事件名称", VanillaStrings.CONTEXT_RANDOM_CHINA_EVENT_NAME)]
        public const string NAME = "II-女祭司";
        [TranslateMsg("随机瓷器事件描述", VanillaStrings.CONTEXT_RANDOM_CHINA_EVENT_DESCRIPTION)]
        public const string DESCRIPTION = "召唤8个御柱";
    }
}
